(function(global) {
  function TinySocket(options) {
    this.options = options || {};
    this.handlers = {};
    this.connected = false;
    this.reconnectTimer = null;
    this.reconnectDelay = 1500;
    this.path = this.options.path || '/socket.io/';
    this.reconnection = this.options.reconnection !== false;
    this.connect();
  }

  TinySocket.prototype.on = function(event, handler) {
    if (!this.handlers[event]) {
      this.handlers[event] = [];
    }
    this.handlers[event].push(handler);
    return this;
  };

  TinySocket.prototype.emitLocal = function(event, payload) {
    var callbacks = this.handlers[event] || [];
    callbacks.forEach(function(callback) {
      callback(payload);
    });
  };

  TinySocket.prototype.socketUrl = function() {
    var protocol = global.location.protocol === 'https:' ? 'wss:' : 'ws:';
    var path = this.path.charAt(0) === '/' ? this.path : '/' + this.path;
    return protocol + '//' + global.location.host + path + '?EIO=4&transport=websocket';
  };

  TinySocket.prototype.connect = function() {
    var self = this;
    if (!global.WebSocket) {
      self.emitLocal('connect_error', new Error('WebSocket is not available'));
      return;
    }

    self.ws = new WebSocket(self.socketUrl());

    self.ws.onmessage = function(message) {
      self.handlePacket(message.data);
    };

    self.ws.onerror = function(error) {
      self.emitLocal('connect_error', error);
    };

    self.ws.onclose = function() {
      var wasConnected = self.connected;
      self.connected = false;
      if (wasConnected) {
        self.emitLocal('disconnect');
      }
      if (self.reconnection) {
        clearTimeout(self.reconnectTimer);
        self.reconnectTimer = setTimeout(function() {
          self.connect();
        }, self.reconnectDelay);
      }
    };
  };

  TinySocket.prototype.handlePacket = function(packet) {
    if (typeof packet !== 'string') {
      return;
    }

    if (packet.charAt(0) === '0') {
      this.ws.send('40');
      return;
    }

    if (packet === '2') {
      this.ws.send('3');
      return;
    }

    if (packet.indexOf('40') === 0) {
      this.connected = true;
      this.emitLocal('connect');
      return;
    }

    if (packet.indexOf('41') === 0) {
      this.connected = false;
      this.emitLocal('disconnect');
      return;
    }

    if (packet.indexOf('42') === 0) {
      try {
        var payload = JSON.parse(packet.slice(2));
        var event = payload[0];
        var data = payload.length > 1 ? payload[1] : undefined;
        this.emitLocal(event, data);
      } catch (error) {
        this.emitLocal('connect_error', error);
      }
      return;
    }

    if (packet.indexOf('44') === 0) {
      this.emitLocal('connect_error', new Error(packet.slice(2)));
    }
  };

  TinySocket.prototype.emit = function(event, data) {
    if (this.connected && this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.send('42' + JSON.stringify([event, data]));
    }
    return this;
  };

  TinySocket.prototype.disconnect = function() {
    this.reconnection = false;
    if (this.ws) {
      this.ws.close();
    }
  };

  global.io = function(options) {
    return new TinySocket(options);
  };
})(window);
